import sys

def solve_anti_sudoku(sudoku):
    # Convert the string representation of the Sudoku into a list of lists
    grid = [list(map(int, row)) for row in sudoku]

    # Function to check if a number appears more than once in a list
    def has_duplicates(lst):
        return len(set(lst)) != len(lst)

    # Function to get all elements in a 3x3 block
    def get_block(x, y):
        block = []
        for i in range(3):
            for j in range(3):
                block.append(grid[x + i][y + j])
        return block

    # List to store the positions of cells to be changed
    changes = []

    # Check rows and columns for duplicates
    for i in range(9):
        row = grid[i]
        col = [grid[j][i] for j in range(9)]
        if not has_duplicates(row):
            for j in range(9):
                if row[j] == 1:
                    changes.append((i, j))
                    break
        if not has_duplicates(col):
            for j in range(9):
                if grid[j][i] == 1:
                    changes.append((j, i))
                    break

    # Check blocks for duplicates
    for i in range(0, 9, 3):
        for j in range(0, 9, 3):
            block = get_block(i, j)
            if not has_duplicates(block):
                for x in range(3):
                    for y in range(3):
                        if grid[i + x][j + y] == 1:
                            changes.append((i + x, j + y))
                            break

    # Make the changes to the grid
    for i, j in changes[:9]:
        grid[i][j] = 1

    # Convert the grid back to a string representation
    result = [''.join(map(str, row)) for row in grid]
    return result

